run_script %{"script" => "local result, err = create_issue({
  title = "Reservations spec missing Test Assertions section",
  description = "The spec for the Reservations component/story does not include a Test Assertions section. Every spec is expected to document the assertions its tests must satisfy; without this section there is no record of what behavior the test suite is meant to verify, making it hard to confirm coverage or catch regressions in acceptance criteria. Please add a Test Assertions section to the Reservations spec.",
  severity = "warning",
  scope = "app"
})
if result == nil then return "failed: " .. err.message end
return result"}

